// The ONE enumeration of the columns crouton adds to every generated table (#2286).
//
// Six generators used to retype these names by hand (PATCH-body exclusion, Drizzle
// reserved list, New* omit list, FK auto-refs, seed fixture, schema-smoke test) and
// agreed only by convention. They import from here now. The flat list is pinned to
// `crouton-core/crouton.manifest.ts` `autoGeneratedFields` by
// tests/unit/utils/system-fields.test.ts — generators don't hold the loaded manifests
// at render time, so parity is asserted there rather than read live.

export const SYSTEM_FIELD_GROUPS = {
  id: ['id'],
  /** Always present — every generated endpoint is team-scoped (@fyit/crouton-auth). */
  team: ['teamId', 'owner'],
  /** Metadata columns, present on every generated table. */
  timestamps: ['createdAt', 'updatedAt'],
  audit: ['createdBy', 'updatedBy'],
  /** Default names; a hierarchy config may rename each (see hierarchyFields). */
  hierarchy: ['parentId', 'path', 'depth', 'order']
} as const

/** Same order as the manifest's autoGeneratedFields. */
export const AUTO_GENERATED_FIELDS: string[] = [
  ...SYSTEM_FIELD_GROUPS.id,
  ...SYSTEM_FIELD_GROUPS.team,
  ...SYSTEM_FIELD_GROUPS.timestamps,
  ...SYSTEM_FIELD_GROUPS.audit
]

/** The metadata columns: timestamps + audit, in that order. */
export function metadataFields(): string[] {
  return [...SYSTEM_FIELD_GROUPS.timestamps, ...SYSTEM_FIELD_GROUPS.audit]
}

/** The auto user-reference columns a list may filter by: owner plus the audit pair. */
export function autoRefFields(): string[] {
  return ['owner', ...SYSTEM_FIELD_GROUPS.audit]
}

export interface HierarchyNames {
  enabled?: boolean
  parentField?: string
  pathField?: string
  depthField?: string
  orderField?: string
}

/** Hierarchy column names (custom or default); empty when hierarchy is off. */
export function hierarchyFields(hierarchy: HierarchyNames | undefined | null): string[] {
  if (!hierarchy?.enabled) return []
  const [parent, path, depth, order] = SYSTEM_FIELD_GROUPS.hierarchy
  return [
    hierarchy.parentField || parent,
    hierarchy.pathField || path,
    hierarchy.depthField || depth,
    hierarchy.orderField || order
  ]
}

/** What a PATCH body may never set: every auto column plus the derived hierarchy columns. */
export function serverManagedFields(): Set<string> {
  return new Set([...AUTO_GENERATED_FIELDS, 'path', 'depth'])
}
